function partial(fn, arg)
    return function(...)
        return fn(arg, ...)
    end
end

-- usage:
-- template([[
--   var name = "{{ action }}";
-- ]], {
--        value=(value and 1 or 0),
--        something=value,
--        javascript=readFile('assets/breaks/main.js')
-- })

function template(s, t)
    local pattern = '{{%s*([^}]-)%s*}}'
    -- allow usage of backticks ` in javascript files
    -- and do not replace ${} placeholder in first place.
    local replace = function(k)
        return tostring(t[k])
                :gsub("`", "\\`")
                :gsub("%$", "\\$")
    end
    --local replace = function(k) return tostring(t[k]) end
    local result, _ = s:gsub(pattern, replace)
    return result
end

function readFileTemplate(path, params)
    -- Double template processing because the inserted code
    -- may itself contain template variables.
    return template(template(readFile(path), params), params)
end

local function runTemplateString(s, params)
    -- Double template processing because the inserted code
    -- may itself contain template variables.
    return template(template(s, params), params)
end

local function getBrowserScript(params)
    local script

    if params.path then
        script = readFileTemplate(params.path, params)
    else
        script = runTemplateString(params.code, params)
    end

    return script
end

local function finishBrowserScript(callback, ok, output, message)
    if not ok then
        debugInfo("Browser script failed: ", message)
    end

    callback(ok, output, message)
end

local function runScriptInBrowser(params, runner, callback)
    assert(callback, "runScriptInBrowser requires callback")
    local script = getBrowserScript(params)

    if params.debug then
        debugInfo(getHammerspoonFunctionName(runner) .. ":\n\n", script)
    end

    local ok, output, message = runner(script)
    finishBrowserScript(callback, ok, output, message)
end

local function runJavaScriptInChromeDevTools(params, callback)
    assert(callback, "runJavaScriptInChromeDevTools requires callback")
    local script = runTemplateString(params.code, params)

    if params.debug then
        debugInfo("Chrome DevTools:\n\n", script)
    end

    helper.chrome.devtools.executeJavascript(script, function(result, err, page)
        if page then
            debugInfo("Chrome DevTools active page: ", page.id, " ", page.title, " ", page.url)
        else
            debugInfo("Chrome DevTools active page: nil")
        end

        finishBrowserScript(callback, err == nil, result, err)
    end)
end

function runJavaScriptInBrowser(params, callback)
    assert(callback, "runJavaScriptInBrowser requires callback")
    if params.browser == "Google DevTools" then
        runJavaScriptInChromeDevTools(params, callback)
        return
    end

    runScriptInBrowser(params, hs.osascript.javascript, callback)
end

function runAppleScriptInBrowser(params, callback)
    runScriptInBrowser(params, hs.osascript.applescript, callback)
end

-- Define a function that checks if a method exists on a userdata object
function doesMethodExist(obj, methodName)
    --return type(obj) == "userdata" and type(rawget(getmetatable(obj), methodName)) == "function"
    return type(rawget(getmetatable(obj), methodName)) == "function"
end

--- isHammerspoonExtension(obj. name) -> bool
--- Function
--- check if an object is an Hammerspoon extension object
---
--- Parameters:
---  * obj - an hammerspoon object
---  * name - A string containing the name of a module (e.g. `"hs.screen"`)
---
--- Returns:
---  * if the object is an extension object
function isHammerspoonExtension(obj, name)
    return getmetatable(obj) == hs.getObjectMetatable(name)
end
